// RFC 4226 (HOTP) / RFC 6238 (TOTP) — uses native Web Crypto, no external deps.
// Works identically in browser and Node 22+ (both expose globalThis.crypto.subtle).

const _Base32 = (typeof module !== 'undefined' && module.exports)
  ? require('./base32.js')
  : window.Base32;

async function hotp(secretBytes, counter, digits = 6, algorithm = 'SHA-1') {
  const counterBuffer = new ArrayBuffer(8);
  const view = new DataView(counterBuffer);
  const high = Math.floor(counter / 0x100000000);
  const low = counter >>> 0;
  view.setUint32(0, high);
  view.setUint32(4, low);

  const key = await crypto.subtle.importKey(
    'raw', secretBytes, { name: 'HMAC', hash: algorithm }, false, ['sign']
  );
  const sig = new Uint8Array(await crypto.subtle.sign('HMAC', key, counterBuffer));
  const offset = sig[sig.length - 1] & 0xf;
  const binCode =
    ((sig[offset] & 0x7f) << 24) |
    ((sig[offset + 1] & 0xff) << 16) |
    ((sig[offset + 2] & 0xff) << 8) |
    (sig[offset + 3] & 0xff);
  const code = (binCode % 10 ** digits).toString().padStart(digits, '0');
  return code;
}

async function totp(secretBase32, opts = {}) {
  const { digits = 6, period = 30, algorithm = 'SHA-1', timestamp = Date.now() } = opts;
  const secretBytes = _Base32.decode(secretBase32);
  const counter = Math.floor(Math.floor(timestamp / 1000) / period);
  return hotp(secretBytes, counter, digits, algorithm);
}

// Codes for the previous/current/next window — useful for clock-skew tolerant verification
async function totpWindow(secretBase32, opts = {}) {
  const { period = 30, timestamp = Date.now() } = opts;
  const base = Math.floor(Math.floor(timestamp / 1000) / period);
  const secretBytes = _Base32.decode(secretBase32);
  const { digits = 6, algorithm = 'SHA-1' } = opts;
  const codes = [];
  for (const delta of [-1, 0, 1]) {
    codes.push(await hotp(secretBytes, base + delta, digits, algorithm));
  }
  return codes;
}

function secondsRemaining(period = 30, timestamp = Date.now()) {
  return period - (Math.floor(timestamp / 1000) % period);
}

function generateSecret(byteLength = 20) {
  const bytes = new Uint8Array(byteLength);
  crypto.getRandomValues(bytes);
  return _Base32.encode(bytes);
}

// otpauth://TYPE/LABEL?secret=...&issuer=...&algorithm=...&digits=...&period=...
function buildOtpauthUri({ type = 'totp', label, secret, issuer, algorithm = 'SHA1', digits = 6, period = 30 }) {
  const encodedLabel = issuer ? `${encodeURIComponent(issuer)}:${encodeURIComponent(label)}` : encodeURIComponent(label);
  const params = new URLSearchParams({ secret, algorithm, digits: String(digits), period: String(period) });
  if (issuer) params.set('issuer', issuer);
  return `otpauth://${type}/${encodedLabel}?${params.toString()}`;
}

function parseOtpauthUri(uri) {
  const url = new URL(uri);
  if (url.protocol !== 'otpauth:') throw new Error('Not an otpauth:// URI');
  const type = url.host; // 'totp' or 'hotp'
  const label = decodeURIComponent(url.pathname.replace(/^\//, ''));
  const params = url.searchParams;
  let issuer = params.get('issuer') || null;
  let account = label;
  if (label.includes(':')) {
    const [issuerFromLabel, acct] = label.split(':');
    if (!issuer) issuer = issuerFromLabel;
    account = acct;
  }
  return {
    type,
    label: account,
    issuer,
    secret: params.get('secret'),
    algorithm: params.get('algorithm') || 'SHA1',
    digits: parseInt(params.get('digits') || '6', 10),
    period: parseInt(params.get('period') || '30', 10),
    counter: params.get('counter') ? parseInt(params.get('counter'), 10) : undefined,
  };
}

const TOTP = { hotp, totp, totpWindow, secondsRemaining, generateSecret, buildOtpauthUri, parseOtpauthUri };
if (typeof module !== 'undefined' && module.exports) {
  module.exports = TOTP;
} else if (typeof window !== 'undefined') {
  window.TOTP = TOTP;
}

