const Base32 = require('./core/base32.js');
const TOTP = require('./core/totp.js');

// RFC 6238 Appendix B test vectors — SHA1, 8 digits, ASCII secret '12345678901234567890'
const secretAscii = '12345678901234567890';
const secretBytes = Buffer.from(secretAscii, 'ascii');
const secretB32 = Base32.encode(secretBytes);
console.log('secret b32:', secretB32);

const vectors = [
  { t: 59, expected: '94287082' },
  { t: 1111111109, expected: '07081804' },
  { t: 1111111111, expected: '14050471' },
  { t: 1234567890, expected: '89005924' },
  { t: 2000000000, expected: '69279037' },
];

(async () => {
  let allPass = true;
  for (const v of vectors) {
    const code = await TOTP.totp(secretB32, { digits: 8, period: 30, algorithm: 'SHA-1', timestamp: v.t * 1000 });
    const pass = code === v.expected;
    if (!pass) allPass = false;
    console.log(v.t, '->', code, pass ? 'PASS' : 'FAIL (expected ' + v.expected + ')');
  }
  console.log(allPass ? 'ALL RFC 6238 VECTORS PASSED' : 'FAILURE');
})();
"

