// Encrypted vault: master password -> PBKDF2-SHA256 (200k iterations) -> AES-256-GCM key.
// The vault is a single JSON blob you can back up anywhere. Losing the device
// doesn't lose the accounts — only losing BOTH the file and the password does.

const PBKDF2_ITERATIONS = 200_000;
const SALT_LENGTH = 16;
const IV_LENGTH = 12;

function toB64(bytes) {
  const bin = String.fromCharCode(...bytes);
  return (typeof btoa !== 'undefined') ? btoa(bin) : Buffer.from(bytes).toString('base64');
}
function fromB64(b64) {
  if (typeof atob !== 'undefined') {
    const bin = atob(b64);
    return Uint8Array.from(bin, c => c.charCodeAt(0));
  }
  return new Uint8Array(Buffer.from(b64, 'base64'));
}

async function deriveKey(password, salt) {
  const enc = new TextEncoder();
  const baseKey = await crypto.subtle.importKey('raw', enc.encode(password), 'PBKDF2', false, ['deriveKey']);
  return crypto.subtle.deriveKey(
    { name: 'PBKDF2', salt, iterations: PBKDF2_ITERATIONS, hash: 'SHA-256' },
    baseKey,
    { name: 'AES-GCM', length: 256 },
    false,
    ['encrypt', 'decrypt']
  );
}

// accounts: array of { id, label, issuer, secret(base32), algorithm, digits, period }
async function encryptVault(accounts, password) {
  const salt = crypto.getRandomValues(new Uint8Array(SALT_LENGTH));
  const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH));
  const key = await deriveKey(password, salt);
  const enc = new TextEncoder();
  const plaintext = enc.encode(JSON.stringify({ accounts, version: 1, savedAt: Date.now() }));
  const ciphertext = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, plaintext));
  return {
    format: 'twofa-vault',
    version: 1,
    kdf: 'PBKDF2-SHA256',
    iterations: PBKDF2_ITERATIONS,
    salt: toB64(salt),
    iv: toB64(iv),
    ciphertext: toB64(ciphertext),
  };
}

async function decryptVault(vaultBlob, password) {
  if (vaultBlob.format !== 'twofa-vault') throw new Error('Not a recognized vault file');
  const salt = fromB64(vaultBlob.salt);
  const iv = fromB64(vaultBlob.iv);
  const ciphertext = fromB64(vaultBlob.ciphertext);
  const key = await deriveKey(password, salt);
  let plaintext;
  try {
    plaintext = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, ciphertext);
  } catch (e) {
    throw new Error('Wrong password or corrupted vault file');
  }
  const dec = new TextDecoder();
  const parsed = JSON.parse(dec.decode(plaintext));
  return parsed.accounts;
}

const Vault = { encryptVault, decryptVault, deriveKey, toB64, fromB64 };
if (typeof module !== 'undefined' && module.exports) {
  module.exports = Vault;
} else if (typeof window !== 'undefined') {
  window.Vault = Vault;
}

