const Vault = require('./core/vault.js');

(async () => {
  const accounts = [
    { id: '1', label: 'jade@example.com', issuer: 'GitHub', secret: 'GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ', algorithm: 'SHA-1', digits: 6, period: 30 },
    { id: '2', label: 'jade', issuer: 'Proton', secret: 'JBSWY3DPEHPK3PXP', algorithm: 'SHA-1', digits: 6, period: 30 },
  ];
  const password = 'correct horse battery staple';

  const blob = await Vault.encryptVault(accounts, password);
  console.log('encrypted blob keys:', Object.keys(blob));
  console.log('ciphertext is not plaintext:', !JSON.stringify(blob).includes('GEZDGNBVGY3TQOJQ'));

  // Round trip with correct password
  const recovered = await Vault.decryptVault(blob, password);
  const roundTripOk = JSON.stringify(recovered) === JSON.stringify(accounts);
  console.log('round-trip integrity:', roundTripOk ? 'PASS' : 'FAIL');

  // Wrong password must fail loudly, not silently return garbage
  try {
    await Vault.decryptVault(blob, 'wrong password');
    console.log('wrong-password rejection: FAIL (decrypted anyway!)');
  } catch (e) {
    console.log('wrong-password rejection: PASS (' + e.message + ')');
  }
})();
"

