    issuer: fields.issuer,
    secret: fields.secret.replace(/\s/g, '').toUpperCase(),
    algorithm: fields.algorithm || 'SHA-1',
    digits: parseInt(fields.digits || 6, 10),
    period: parseInt(fields.period || 30, 10),
