/* ---------- Camera QR scanning ---------- */
let scanStream = null, scanRAF = null;
async function startScanner() {
  const video = $('#scan-video');
  const canvas = $('#scan-canvas');
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  $('#scan-error').textContent = '';
  try {
    scanStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
  } catch (err) {
    $('#scan-error').textContent = 'Camera access denied or unavailable. Use manual entry or paste a link instead.';
    return;
  }
  video.srcObject = scanStream;
  await video.play();
  const loop = () => {
    if (!scanStream) return;
    if (video.readyState === video.HAVE_ENOUGH_DATA) {
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
      const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const result = jsQR(imageData.data, imageData.width, imageData.height);
      if (result && result.data && result.data.startsWith('otpauth://')) {
        stopScanner();
        try {
          const parsed = TOTP.parseOtpauthUri(result.data);
          addAccountFromFields({
            label: parsed.label, issuer: parsed.issuer, secret: parsed.secret,
            algorithm: 'SHA-' + parsed.algorithm.replace('SHA', ''), digits: parsed.digits, period: parsed.period,
          });
        } catch (err) {
          $('#scan-error').textContent = 'Scanned a QR code but could not read it as a 2FA setup code.';
        }
        return;
      }
    }
    scanRAF = requestAnimationFrame(loop);
  };
  scanRAF = requestAnimationFrame(loop);
}
function stopScanner() {
  if (scanRAF) cancelAnimationFrame(scanRAF);
  scanRAF = null;
  if (scanStream) scanStream.getTracks().forEach(t => t.stop());
  scanStream = null;
}

/* ---------- Settings: export / import / change password / lock ---------- */
$('#nav-settings').onclick = () => showModal('settings');
$('#settings-close').onclick = () => closeModal('settings');
$('#settings-lock').onclick = () => { closeModal('settings'); lockVault(); };

$('#settings-export').onclick = async () => {
  const blob = await Vault.encryptVault(state.accounts, state.password);
  const text = JSON.stringify(blob, null, 2);
  const file = new Blob([text], { type: 'application/json' });
  const url = URL.createObjectURL(file);
  const a = document.createElement('a');
  a.href = url;
  a.download = `twofa-vault-${new Date().toISOString().slice(0, 10)}.json`;
  a.click();
  URL.revokeObjectURL(url);
  toast('Vault exported — store this file somewhere safe');
};

$('#settings-import').onclick = () => $('#import-file-input').click();
$('#import-file-input').onchange = async (e) => {
  const file = e.target.files[0];
  if (!file) return;
  const text = await file.text();
  let blob;
  try { blob = JSON.parse(text); } catch { return toast('Not a valid vault file'); }
  const pw = prompt('Enter the password for this vault file:');
  if (pw == null) return;
  try {
    const imported = await Vault.decryptVault(blob, pw);
    const merged = [...state.accounts];
    for (const acc of imported) {
      if (!merged.some(a => a.secret === acc.secret && a.label === acc.label)) {
        merged.push({ ...acc, id: uid() });
      }
    }
    state.accounts = merged;
    await persist();
    renderAccounts();
    closeModal('settings');
    toast(`Imported ${imported.length} account(s)`);
  } catch (err) {
    toast(err.message);
  }
  e.target.value = '';
};

$('#change-pw-form').onsubmit = async (e) => {
  e.preventDefault();
  const cur = $('#cur-pw').value, next = $('#new-pw').value, next2 = $('#new-pw-confirm').value;
  $('#change-pw-error').textContent = '';
  if (cur !== state.password) return ($('#change-pw-error').textContent = 'Current password is wrong.');
  if (next.length < 8) return ($('#change-pw-error').textContent = 'New password must be at least 8 characters.');
  if (next !== next2) return ($('#change-pw-error').textContent = "New passwords don't match.");
  state.password = next;
  await persist();
  $('#change-pw-form').reset();
  toast('Password changed');
};

/* ---------- Init ---------- */
window.addEventListener('DOMContentLoaded', () => {
  showScreen('lock');
  initLockScreen();
  if ('serviceWorker' in navigator) {
    navigator.serviceWorker.register('./sw.js').catch(() => {});
  }
});

