const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({
    args: ['--use-fake-ui-for-media-stream', '--use-fake-device-for-media-stream'],
  });
  const context = await browser.newContext({ permissions: ['camera'] });
  const page = await context.newPage();
  page.on('console', (msg) => { if (msg.type() === 'error') console.log('BROWSER ERROR:', msg.text()); });
  page.on('pageerror', (err) => console.log('PAGE EXCEPTION:', err.message));

  const results = [];
  const check = (name, cond) => { results.push({ name, pass: !!cond }); console.log((cond ? 'PASS' : 'FAIL'), '-', name); };

  await page.goto('http://127.0.0.1:8765/index.html');

  // 1. First-run: should show "Create your vault"
  await page.waitForSelector('#lock-title');
  check('shows create-vault on first run', (await page.textContent('#lock-title')).includes('Create'));

  // 2. Create vault
  await page.fill('#lock-password', 'test-master-pw-123');
  await page.fill('#lock-password-confirm', 'test-master-pw-123');
  await page.click('#lock-submit');
  await page.waitForSelector('#screen-main.active');
  check('enters main screen after vault creation', await page.isVisible('#screen-main'));
  check('empty state shown with no accounts', (await page.textContent('#account-list')).includes('No accounts'));

  // 3. Add an account manually using the known RFC 6238 test secret
  await page.click('#fab-add');
  await page.waitForSelector('#modal-add.active');
  await page.fill('#add-issuer', 'TestService');
  await page.fill('#add-label', 'jade@example.com');
  await page.fill('#add-secret', 'GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ'); // = ASCII "12345678901234567890"
  await page.selectOption('#add-digits', '8');
  await page.fill('#add-period', '30');
  await page.click('#add-form button[type=submit]');
  await page.waitForSelector('.account-row');
  check('account row appears after adding', await page.isVisible('.account-row'));

  // 4. Verify the displayed code is a REAL, correct TOTP code (compute expected value independently)
  await page.waitForTimeout(1200); // let the tick() loop populate the code
  const displayedCode = (await page.textContent('.account-row .code')).replace(/\s/g, '');
  const now = Date.now();
  const TOTP = require('./core/totp.js');
  const expected = await TOTP.totp('GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ', { digits: 8, period: 30, algorithm: 'SHA-1', timestamp: now });
  check(`displayed code (${displayedCode}) matches independently computed TOTP (${expected})`, displayedCode === expected);

  // 5. Reload the page (simulates closing and reopening the app) — must ask to unlock, not lose data
  await page.reload();
  await page.waitForSelector('#lock-title');
  check('after reload, asks to Unlock (not Create) — vault persisted', (await page.textContent('#lock-title')).includes('Unlock'));

  await page.fill('#lock-password', 'test-master-pw-123');
  await page.click('#lock-submit');
  await page.waitForSelector('.account-row');
  const codeAfterReload = (await page.textContent('.account-row .code')).replace(/\s/g, '');
  const expected2 = await TOTP.totp('GEZDGNBVGY3TQOJQGEZDGNBVGY3TQOJQ', { digits: 8, period: 30, algorithm: 'SHA-1', timestamp: Date.now() });
  check('account survives reload and still produces a correct live code', codeAfterReload === expected2);

  // 6. Wrong password on unlock should be rejected
  await page.click('#nav-settings');
  await page.click('#settings-lock');
  await page.waitForSelector('#lock-title');
  await page.fill('#lock-password', 'totally-wrong-password');
  await page.click('#lock-submit');
  await page.waitForTimeout(300);
  const lockErr = await page.textContent('#lock-error');
  check('wrong password on unlock shows an error, does not enter app', lockErr.length > 0 && await page.isVisible('#screen-lock'));

  // 7. Correct unlock again + export vault produces a downloadable file
  await page.fill('#lock-password', 'test-master-pw-123');
  await page.click('#lock-submit');
  await page.waitForSelector('.account-row');
  await page.click('#nav-settings');
  const [download] = await Promise.all([
    page.waitForEvent('download'),
    page.click('#settings-export'),
  ]);
  const path = await download.path();
  const fs = require('fs');
  const exportedContent = JSON.parse(fs.readFileSync(path, 'utf8'));
  check('exported vault file has expected encrypted format', exportedContent.format === 'twofa-vault' && !!exportedContent.ciphertext);
  check('exported vault does not contain the plaintext secret', !JSON.stringify(exportedContent).includes('GEZDGNBVGY3TQOJQ'));

  await browser.close();

  const failed = results.filter(r => !r.pass);
  console.log('\n' + (failed.length === 0 ? `ALL ${results.length} CHECKS PASSED` : `${failed.length} CHECK(S) FAILED`));
  process.exit(failed.length === 0 ? 0 : 1);
})();

