    await page.fill('#lock-password-confirm', 'pw12345678');
    await page.click('#lock-submit');
    await page.waitForSelector('#screen-main.active');

    await page.click('#fab-add');
    await page.click('.add-tab[data-tab=scan]');
    console.log('waiting for scanner to detect QR from fake camera feed...');
